import { buildPdfExport, type BuildExportInput } from "../../adapters/pdf/export";
import { PdfEngineError } from "../../domain/pdf";

// Preview has no save, download or validated-output protocol. Generated bytes
// are consumed only by the caller's private PDF.js preview document.
const scope=self as unknown as {onmessage:((event:MessageEvent<{id:string;input:BuildExportInput}>)=>void)|null;postMessage:(message:unknown,transfer?:Transferable[])=>void};
scope.onmessage=event=>{
  const {id,input}=event.data;
  void buildPdfExport(input,undefined,()=>scope.postMessage({id,kind:"progress"}))
    .then(result=>scope.postMessage({id,ok:true,bytes:result.bytes},[result.bytes.buffer as ArrayBuffer]))
    .catch(error=>scope.postMessage({id,ok:false,error:{code:error instanceof PdfEngineError?error.code:"PREVIEW_FAILED",message:error instanceof PdfEngineError?error.message:"記入結果を表示できませんでした。",issues:error instanceof PdfEngineError?error.issues:[]}}));
};
